from .repository import put_contact, existing_emails

_ROW_FIELDS = frozenset(("email", "name"))

def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)

def _normalize_row(row):
    if not isinstance(row, dict):
        raise ValueError("row must be an object")
    keys = set(row)
    unknown = keys - _ROW_FIELDS
    if unknown:
        raise ValueError(f"unknown fields: {sorted(unknown)}")
    missing = _ROW_FIELDS - keys
    if missing:
        raise ValueError(f"missing fields: {sorted(missing)}")
    email, name = row["email"], row["name"]
    if not isinstance(email, str) or not isinstance(name, str):
        raise ValueError("email and name must be strings")
    email = email.strip()
    name = name.strip()
    if email.count("@") != 1:
        raise ValueError("email must contain exactly one @")
    local, domain = email.split("@")
    if not local or not domain:
        raise ValueError("email must have nonempty local and domain parts")
    if any(ch.isspace() for ch in email):
        raise ValueError("email must not contain whitespace")
    if not name:
        raise ValueError("name must not be empty")
    return email.lower(), name

def import_contacts(connection, rows):
    if not isinstance(rows, (list, tuple)):
        raise ValueError("rows must be a list")
    batch = {}
    for row in rows:
        email, name = _normalize_row(row)
        if email in batch:
            raise ValueError(f"duplicate email in batch: {email}")
        batch[email] = name
    if not batch:
        return {"inserted": 0, "updated": 0}
    with connection:
        connection.execute("BEGIN IMMEDIATE")
        existing = existing_emails(connection, list(batch))
        for email, name in batch.items():
            put_contact(connection, email, name)
    updated = len(existing)
    return {"inserted": len(batch) - updated, "updated": updated}
